$t['Final test: complete a sandbox purchase, confirm an HTTP 200 delivery in Stripe, then check the wallet or rental, subscription access and video playback. Also test a declined card and 3D Secure. Never retry a charged payment just because access is still pending.'] = 'Test końcowy: dokonaj zakupu w trybie sandbox, potwierdź dostarczenie z kodem HTTP 200 w Stripe, a następnie sprawdź portfel lub wypożyczenie, dostęp do subskrypcji i odtwarzanie filmu. Przetestuj też odrzuconą kartę i 3D Secure. Nigdy nie ponawiaj obciążonej płatności tylko dlatego, że dostęp wciąż oczekuje.';
$t['Final test: complete a sandbox purchase with a Personal sandbox buyer, confirm an HTTP 200 webhook delivery in developer.paypal.com, then check the wallet, rental, subscription and video playback. Never retry a paid purchase just because access is still pending.'] = 'Test końcowy: dokonaj zakupu w trybie sandbox za pomocą kupującego Personal sandbox, potwierdź dostarczenie webhooka z kodem HTTP 200 na developer.paypal.com, a następnie sprawdź portfel, wypożyczenie, subskrypcję i odtwarzanie filmu. Nigdy nie ponawiaj opłaconego zakupu tylko dlatego, że dostęp wciąż oczekuje.';
