$t['The <a href=\'{videoLink}\'>{videoName}</a> video was reported as inappropriate from {user} '] = 'Wideo <a href=\'{videoLink}\'>{videoName}</a> zostało zgłoszone jako niestosowne od {user} ';
$t['The account could not be connected. Please try again.'] = 'Nie udało się połączyć konta. Spróbuj ponownie.';
$t['The administrator will verify the payment'] = 'Administrator zweryfikuje płatność';
$t['The broadcast was interrupted. Please try again.'] = 'Transmisja została przerwana. Spróbuj ponownie.';
$t['The camera or microphone request was interrupted. Please try again.'] = 'Żądanie dostępu do kamery lub mikrofonu zostało przerwane. Spróbuj ponownie.';
