$t['The captcha is wrong'] = 'Kod CAPTCHA jest nieprawidłowy';
$t['The captcha session expired, please try again'] = 'Sesja captcha wygasła, spróbuj ponownie';
$t['The change could not be saved'] = 'Nie udało się zapisać zmiany';
$t['The check could not finish. Reload the page and try again.'] = 'Nie udało się zakończyć sprawdzania. Odśwież stronę i spróbuj ponownie.';
$t['The comment is empty'] = 'The comment is empty';
$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'Commit określa rewizję Git pobraną na tym serwerze; lokalne zmiany w plikach nie są uwzględniane. Tag Git jest wyświetlany, gdy wskazuje bezpośrednio na ten commit.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Usługa Companion Chat jest obecnie niedostępna. Poproś administratora witryny o sprawdzenie połączenia wtyczki AI.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'Nie udało się odnowić połączenia. Połącz ponownie swoje konto.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'Połączenie wygasło i nie udało się go odnowić. Połącz ponownie swoje konto.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'Połączenie z miejscem docelowym zostało zerwane w trakcie transmisji. Może to być tymczasowy problem z siecią; FFMPEG spróbuje połączyć się ponownie.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'Połączenie z YouTube zostało przerwane. Przesyłanie zostało wstrzymane i można je wznowić.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'Połączenie zostało przerwane. Sprawdź swoje konto przed ponowną próbą tej subskrypcji.';
$t['The connection was renewed.'] = 'Połączenie zostało odnowione.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Okno połączenia zostało zamknięte przed zakończeniem autoryzacji. Żadne konto nie zostało połączone.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'Przekonwertowane pliki zostały zachowane. Skontaktuj się z administratorem witryny, aby ponowić transfer; nie musisz ponownie przesyłać filmu.';
$t['The converted video could not be sent back to this site.'] = 'Nie udało się odesłać przekonwertowanego filmu do tej witryny.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Klienci wybranej karty. Wyszukuj, sortuj, kopiuj adresy e-mail lub eksportuj wszystko do arkusza kalkulacyjnego.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Osiągnięto dzienny limit przesyłania na YouTube dla tej witryny. Przesyłanie będzie ponownie dostępne po północy czasu pacyficznego. Spróbuj ponownie później.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Wersja bazy danych zmienia się tylko po zastosowaniu migracji bazy danych. Nie musi być zgodna z tagiem wydania ani commitem.';
$t['The default'] = 'Domyślny';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Docelowy serwer RTMP odrzucił połączenie. Sprawdź URL strumienia i upewnij się, że serwer jest online.';
$t['The destination server requires authentication. Check the stream key.'] = 'Serwer docelowy wymaga uwierzytelnienia. Sprawdź klucz strumienia.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Serwer docelowy zwrócił błąd 403. Klucz strumienia może być nieprawidłowy lub wygasły.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Docelowy film został usunięty lub to konto nie może go edytować. Sprawdź film i dostęp konta w witrynie.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'Pobieranie jest kontrolowane przez system, nie ma nic do sprawdzenia na użytkowniku';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'Pozwolenie na pobieranie jest dostępne w całej witrynie, więc nie ma nic do sprawdzenia na filmie';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'Pozwolenie na pobieranie dotyczy całej witryny, więc nie ma nic do sprawdzenia w filmie';
$t['The email is invalid'] = 'E-mail jest nieprawidłowy';
$t['The encoder could not download the original file.'] = 'Enkoder nie mógł pobrać oryginalnego pliku.';
$t['The encoder could not find this video on the site.'] = 'Enkoder nie mógł znaleźć tego filmu w witrynie.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'Enkoder nie potwierdził dodania filmu do kolejki. Spróbuj ponownie.';
$t['The encoder is running out of disk space'] = 'Na enkoderze kończy się miejsce na dysku';
$t['The encoder reported an unexpected error.'] = 'Enkoder zgłosił nieoczekiwany błąd.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Proces kodowania nieoczekiwanie się zatrzymał, a automatyczne ponowne próby również się nie powiodły.';
$t['The encoding queue is stalled'] = 'Kolejka kodowania utknęła';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Nie udało się sfinalizować zakupu wydarzenia. Płatność z portfela nie została pobrana. Sprawdź saldo przed ponowną próbą.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Nie udało się przekonwertować pliku. Może być uszkodzony lub w formacie nieobsługiwanym przez enkoder.';
$t['The file must be an .vtt file!'] = 'Plik musi być formatu .vtt !';
$t['The file must be an .vtt or .srt file!'] = 'Plik musi być plikiem .vtt lub .srt!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'Ostateczna opłata jest naliczana według czasu trwania zmierzonego podczas przetwarzania. Wymagany jest połączony portfel Marketplace.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Poniższy film zawiera materiały nieodpowiednie dla dzieci w wieku 17 lat i młodszych.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'Poniższy film zawiera materiały, które mogą być nieodpowiednie dla dzieci w wieku 17 lat i młodszych.';
$t['The form to signup will not exists'] = 'Formularz do rejestracji nie będzie istniał';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Kod podarunkowy został anulowany. Jeśli to nieoczekiwane, skontaktuj się z naszym zespołem wsparcia.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Kod podarunkowy jest obecnie nieaktywny. Sprawdź ponownie później lub skontaktuj się z pomocą techniczną.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Powyższe informacje są zgodne z naszymi oficjalnymi rejestrami i potwierdzają autentyczność tego certyfikatu.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Strumień wejściowy zawiera nieprawidłowe dane. Źródłowy HLS może nie być jeszcze gotowy lub strumień został przerwany.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Zainstalowany pakiet PHP zawiera obie poprawki, ale ten proces WWW nadal używa kopii załadowanej przed aktualizacją. Uruchom ponownie Apache lub PHP-FPM.';
$t['Their last plans add up to %s'] = 'Ich ostatnie plany sumują się do %s';
$t['The list was limited to the first %s results.'] = 'Lista została ograniczona do pierwszych %s wyników.';
$t['The live service could not complete the request. Please try again.'] = 'Usługa transmisji na żywo nie mogła zrealizować żądania. Spróbuj ponownie.';
$t['The live that was still being sent to this destination was stopped.'] = 'Transmisja na żywo, która była nadal wysyłana do tego miejsca docelowego, została zatrzymana.';
$t['Theme for Style:'] = 'Motyw dla stylu';
$t['Themes'] = 'Motyw';
$t['The number of lines in both columns must be the same'] = 'Liczba wierszy w obu kolumnach musi być taka sama';
$t['The original file for this video does not exists anymore'] = 'Oryginalny plik tego filmu wideo już nie istnieje';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'Wtyczka uprawnień nie jest zainstalowana. Zainstaluj ją, jeśli chcesz dostosować uprawnienia.';
$t['The plugin is disabled'] = 'Wtyczka jest wyłączona';
$t['The program is empty'] = 'Program jest pusty';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Nie udało się sfinalizować zakupu. Płatność z portfela nie została pobrana. Sprawdź saldo przed ponowną próbą.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'Ten kod podarunkowy ma nieznany status. Skontaktuj się z pomocą techniczną.';
$t['There, you can set'] = 'Tam możesz ustawić';
$t['There are no notifications'] = 'Nie ma żadnych powiadomień';
$t['There are no upcoming events for this channel'] = 'Ten kanał nie ma nadchodzących wydarzeń';
$t['There are various kinds of media you can integrate here. They are working different'] = 'Istnieje wiele rodzajów mediów, które można tutaj zintegrować.';
$t['There are various kinds of media you can integrate here. They are working diffrent'] = 'Istnieją różne rodzaje mediów, które można tutaj zintegrować. Działają inaczej';
$t['The recover pass does not match!'] = 'Odzyskane hasło nie pasuje !';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'Zwykły formularz logowania nie będzie istniał, jeśli zaznaczysz to, będzie miał tylko opcję logowania społecznościowego lub LDAP';
$t['The regular form to signin will not exist, if you check this will only havesocial login or LDAP option'] = 'Zwykły formularz logowania nie będzie istniał, jeśli zaznaczysz tę opcję, będzie dostępna tylko opcja logowania społecznościowego dla LDAP';
$t['There is missing data to recover your password'] = 'Brakuje danych do odzyskania hasła';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Nie ma jeszcze planu Pay Per View. Utwórz go we wtyczce Pay-Per-View, w zakładce Plany PPV.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Nie ma jeszcze planu, który może zawierać filmy. Utwórz go w zakładce Plany PPV, a następnie wróć tutaj.';
$t['There is no streaming now'] = 'Nie ma teraz strumieniowania';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Numer wydania i wersja bazy danych AVideo są niezależne. Stan aktualizacji kodu jest określany na podstawie historii commitów.';
$t['The request to the social network failed. Please try again later.'] = 'Żądanie do serwisu społecznościowego nie powiodło się. Spróbuj ponownie później.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Serwer restreamera nie może połączyć się z miejscem docelowym. Sprawdź łączność sieciową.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Ten sam alert jest powtarzany najwyżej co %s, dopóki problem trwa.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Ten sam alert jest powtarzany najwyżej co kilka godzin, dopóki problem trwa.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'Wybrana kamera lub mikrofon jest niedostępny. Wybierz inne urządzenie.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Wybrana pozycja jest wyróżniona na prawdziwej stronie. Podgląd mobilny zmienia tylko pozycje reklam; reszta strony korzysta z urządzenia Twojej przeglądarki.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Wybrana pozycja jest obrysowana na prawdziwej stronie Twojej witryny i podąża za pozycją wybraną poniżej. Podgląd mobilny zmienia tylko pozycje reklam; reszta strony korzysta z urządzenia Twojej przeglądarki.';
$t['The server is not ready'] = 'Serwer nie jest gotowy';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Witryna jest obecnie niedostępna z powodu problemu z bazą danych. Pracujemy nad jak najszybszym rozwiązaniem problemu.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Witryna jest tymczasowo niedostępna, ponieważ dysk serwera jest pełny. Pracujemy nad tym problemem i wkrótce wrócimy.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Witryna przechodzi prace konserwacyjne, ponieważ dysk serwera jest prawie pełny. Rozwiązujemy problem i wkrótce wrócimy.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Witryna odmówiła dostępu. Odnów dostęp konta enkodera i sprawdź jego uprawnienia do przesyłania.';
$t['The site will display only a login form to un authenticated users'] = 'Witryna wyświetli tylko formularz logowania dla nieuwierzytelnionych użytkowników';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Strumień źródłowy zakończył się. Jeśli transmisja została zatrzymana celowo, jest to normalne.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'Podział jest włączony: odwiedzający na komputerach nie widzą teraz tego banera, widzą lewą i prawą połowę.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'Strumień ma nieciągłości znaczników czasu. Może to powodować buforowanie lub problemy z odtwarzaniem na platformie docelowej.';
$t['The subtitle has not been copied to the player yet.'] = 'Napisy nie zostały jeszcze skopiowane do odtwarzacza.';
$t['The subtitle is already on the player.'] = 'Napisy są już w odtwarzaczu.';
$t['The subtitle was copied to the player.'] = 'Napisy zostały skopiowane do odtwarzacza.';
$t['The subtitle will be available when processing finishes.'] = 'Napisy będą dostępne po zakończeniu przetwarzania.';
$t['The upload could not be started. Please try again.'] = 'Nie udało się rozpocząć przesyłania. Spróbuj ponownie.';
$t['The upload did not start. Click Resume to try again.'] = 'Przesyłanie nie rozpoczęło się. Kliknij Wznów, aby spróbować ponownie.';
$t['The upload to YouTube started. You can follow its progress below, it continues even if you close this window.'] = 'Rozpoczęto przesyłanie na YouTube. Możesz śledzić postęp poniżej; będzie kontynuowane nawet po zamknięciu tego okna.';
$t['The upload was canceled.'] = 'Przesyłanie zostało anulowane.';
$t['The upload was interrupted. Click Resume to continue from where it stopped.'] = 'Przesyłanie zostało przerwane. Kliknij Wznów, aby kontynuować od miejsca, w którym zostało zatrzymane.';
$t['The upload was resumed.'] = 'Przesyłanie zostało wznowione.';
$t['the user is inactive'] = 'użytkownik jest nieaktywny';
$t['The user is not active'] = 'Użytkownik nie jest aktywny';
$t['The username must be an email'] = 'Nazwa użytkownika musi być adresem e-mail';
$t['The user will be able to edit their name and CPF.'] = 'Użytkownik będzie mógł edytować swoje imię i nazwisko oraz CPF.';
$t['The video could not be published. Please try again later.'] = 'Nie udało się opublikować filmu. Spróbuj ponownie później.';
$t['The video file could not be found on this server, so it cannot be sent to YouTube.'] = 'Nie znaleziono pliku wideo na tym serwerze, więc nie można go wysłać na YouTube.';
$t['The video is empty'] = 'The video is empty';
$t['The video was published.'] = 'Film został opublikowany.';
$t['The website pages do not display this position, so there is nothing to preview.'] = 'Strony witryny nie wyświetlają tej pozycji, więc nie ma czego podglądać.';
$t['The website pages do not display this position at the moment. Images saved here are only returned by the API.'] = 'Strony witryny obecnie nie wyświetlają tej pozycji. Zapisane tutaj obrazy są zwracane tylko przez API.';
$t['They are likely to leave at renewal time. Invite them back with a suggested course or a live class.'] = 'Prawdopodobnie zrezygnują przy odnowieniu. Zaproś ich ponownie, proponując kurs lub zajęcia na żywo.';
$t['They have paid %s in total'] = 'Zapłacili łącznie %s';
$t['The YouTube authorization could not be renewed because the authorization service did not answer. Please try again in a few minutes.'] = 'Nie udało się odnowić autoryzacji YouTube, ponieważ usługa autoryzacji nie odpowiedziała. Spróbuj ponownie za kilka minut.';
$t['The YouTube categories could not be loaded, YouTube will choose one.'] = 'Nie udało się wczytać kategorii YouTube, YouTube wybierze jedną.';
$t['The YouTube integration is not configured correctly. Please contact the site administrator.'] = 'Integracja z YouTube nie jest poprawnie skonfigurowana. Skontaktuj się z administratorem witryny.';
$t['The {videoName} video was reported as inappropriate'] = 'Film {videoName} został zgłoszony jako nieodpowiedni';
$t['Third Party Ads'] = 'Reklamy zewnętrzne';
$t['This account has been disabled. Contact support for details.'] = 'To konto zostało wyłączone. Skontaktuj się z pomocą techniczną, aby uzyskać szczegóły.';
$t['This account is disabled because the connected marketplace wallet balance ran out. Add credits to your marketplace wallet to reactivate automatically - content is at risk of deletion after 24 hours.'] = 'To konto jest wyłączone, ponieważ wyczerpało się saldo połączonego portfela marketplace. Doładuj portfel marketplace, aby konto zostało automatycznie ponownie aktywowane - po 24 godzinach treści mogą zostać usunięte.';
$t['This action can not be recovered!'] = 'Tej akcji nie da się odzyskać !';
$t['This action cannot be undone. The user will need to confirm their identity again.'] = 'Tej operacji nie można cofnąć. Użytkownik będzie musiał ponownie potwierdzić swoją tożsamość.';
$t['This ad goes on the LEFT half of the banner.'] = 'Ta reklama jest umieszczana w LEWEJ połowie banera.';
$t['This ad goes on the RIGHT half of the banner.'] = 'Ta reklama jest umieszczana w PRAWEJ połowie banera.';
$t['This administration page is unavailable. Update AVideo and try again.'] = 'Ta strona administracyjna jest niedostępna. Zaktualizuj AVideo i spróbuj ponownie.';
$t['This ad position is not displayed on this page.'] = 'Ta pozycja reklamy nie jest wyświetlana na tej stronie.';
